# [HELPER] translation_client.py – Local configuration and client helper utilities for General Text Translation\n# Uses DeepL API (concrete provider)\nimport os\nimport requests\nfrom typing import Dict, Any\n\n# Provider‑specific signal / configuration\nDEEPL_AUTH_KEY = os.getenv('DEEPL_AUTH_KEY')\n\nif not DEEPL_AUTH_KEY:\n    raise RuntimeError('Set DEEPL_AUTH_KEY environment variable with your DeepL auth key.')\n\nBASE_URL = 'https://api.deepl.com/v2'\n\ndef _deepL_request(endpoint: str, payload: Dict[str, Any]) -> Dict[str, Any]:\n    \"\"\"Low‑level request helper for DeepL API.\n\n    Args:\n        endpoint: API endpoint without leading slash, e.g. 'translate'.\n        payload: Dictionary of query / form parameters.\n\n    Returns:\n        Parsed JSON response.\n    \"\"\"\n    url = f\"{BASE_URL}/{endpoint}\"\n    response = requests.post(url, data=payload)\n    response.raise_for_status()\n    return response.json()\n\ndef translate_text(text: str, target_lang: str = 'EN') -> str:\n    \"\"\"Translate a single string via DeepL.\n\n    Args:\n        text: Source text.\n        target_lang: Target language code.\n\n    Returns:\n        Translated text.\n    \"\"\"\n    resp = _deepL_request('translate', {\n        'auth_key': DEEPL_AUTH_KEY,\n        **payload,\n    })\n    return resp['translations'][0]['text']\n\n# Helper to translate list of strings (preserves order)\ndef translate_batch(texts: list[str], target_lang: str = 'EN') -> list[str]:\n    results = []\n    for txt in texts:\n        results.append(translate_text(txt, target_lang))\n    return results\n\n# Example usage (guarded)\nif __name__ == '__main__':\n    test = 'Bonjour le monde!'\n    print('Translated:', translate_text(test, target_lang='EN'))